const out = [];
for (const item of items) {
  const json = item.json || {};
  const props = json.properties || {};

  // titulo (type: title)
  const tituloRaw = props.titulo || props.Name || props.nome || {};
  const titulo = (tituloRaw.title || []).map(t => t.plain_text || '').join('').trim() || String(json.titulo || '').trim();

  // descricao (type: rich_text)
  const descRaw = props.descricao || props.description || {};
  const descricao = (descRaw.rich_text || []).map(t => t.plain_text || '').join('').trim() || String(json.descricao || '').trim();

  // modo_execucao (type: select)
  const modoRaw = props.modo_execucao || {};
  const modo = ((modoRaw.select && modoRaw.select.name) || String(json.modo_execucao || 'research_auto')).trim().toLowerCase();

  out.push({
    json: {
      ...json,
      titulo,
      descricao,
      modo_execucao: modo,
      timestamp_execucao: new Date().toISOString()
    }
  });
}
return out;

return items.map(item => {
  const { titulo, descricao } = item.json;
  const prompt = `Você é um analista estratégico de negócios digitais com foco em gastronomia, operação, IA e monetização.

TEMA CENTRAL:
${titulo}

CONTEXTO ADICIONAL:
${descricao}

Sua missão:
1. Encontrar 10 oportunidades de conteúdo ou produto
2. Identificar dores de mercado
3. Sugerir ângulos de posicionamento
4. Sugerir quais ideias têm maior potencial de monetização
5. Responder SOMENTE em JSON válido

Formato obrigatório:
{
  "resumo_estrategico": "",
  "dores": ["", ""],
  "oportunidades": [{"titulo": "", "tipo": "conteudo|produto|servico", "potencial": 1, "justificativa": ""}],
  "prioridade_recomendada": {"titulo": "", "motivo": ""}
}`;
  return { json: { ...item.json, prompt_openai: prompt } };
});

function tryParse(text) {
  try { return JSON.parse(text); } catch(e) {
    const m = String(text).match(/\{[\s\S]*\}/);
    if (m) return JSON.parse(m[0]);
    throw new Error('Parse falhou');
  }
}
return items.map(item => {
  const raw = (item.json.message && item.json.message.content) || item.json.text || item.json.response || item.json.output || item.json.content || JSON.stringify(item.json);
  const parsed = tryParse(raw);
  return { json: { ...item.json, resultado_estruturado: parsed, saida_json: JSON.stringify(parsed, null, 2), observacoes: 'research_auto concluído' } };
});

