return items.map(item => {
  const modo = item.json.modo_execucao || '';
  const resultado = item.json.resultado_estruturado || {};
  let score = 5;

  if (modo === 'research_auto') {
    const ops = resultado.oportunidades || [];
    const potenciais = ops.map(o => Number(o.potencial || 0));
    score = potenciais.length
      ? Math.round(potenciais.reduce((a, b) => a + b, 0) / potenciais.length)
      : 5;
  }
  if (modo === 'dan_koe') {
    const posts = resultado.posts_validacao || [];
    score = posts.length >= 5 ? 8 : 6;
  }
  if (modo === 'produto') {
    const entregaveis = resultado.entregaveis || [];
    score = entregaveis.length >= 3 ? 9 : 7;
  }

  return { json: { ...item.json, score_ia: score, status: 'concluído' } };
});
